package com.abyssredemption.abstool.client.serverstats;
import com.abyssredemption.abstool.client.serverstats.model.*; import com.abyssredemption.abstool.client.serverstats.network.*; import java.util.*;
public final class ServerStatsState { private ServerStatsAvailability availability=ServerStatsAvailability.UNKNOWN; private int capabilities; private String weekKey=""; private final Map<String,ClientLeaderboardPage> pages=new HashMap<>(); private final Map<String,Long> received=new HashMap<>(); public ServerStatsAvailability availability(){return availability;} public void availability(ServerStatsAvailability a){availability=a;} public int capabilities(){return capabilities;} public String weekKey(){return weekKey;} public void hello(int c,String w){capabilities=c;weekKey=w;availability=ServerStatsAvailability.READY;} public void clear(){pages.clear();received.clear();availability=ServerStatsAvailability.UNKNOWN;capabilities=0;weekKey="";} public void put(ClientLeaderboardPage p){String k=p.type()+":"+p.page();pages.put(k,p);received.put(k,System.currentTimeMillis());} public ClientLeaderboardPage get(LeaderboardType t,int p){return pages.get(t+":"+p);} public boolean fresh(LeaderboardType t,int p){Long at=received.get(t+":"+p);return at!=null&&System.currentTimeMillis()-at<10000;} public boolean supports(LeaderboardType t){return (capabilities&(1<<t.networkId()))!=0;} }
